name: nxeon-checkout-conversion-research
description: What the checkout/conversion evidence actually says for the Nxeon deploy wizard — and which widely-quoted numbers are fabricated
metadata:
  type: reference
---

Research done 2026-09-05 for the single-page deploy wizard. Sources are
Baymard, NN/g, peer-reviewed journals and the competitors' own live flows.

**The premise "one page converts better" is not supported.** Baymard's position
is that page count is close to irrelevant — *"the number of form fields impacts
overall usability far more than the number of steps."* Average checkout is 11.3
fields; most sites need 8. So cut FIELDS, not pages.

**The single highest-leverage move is pre-selected defaults.** DigitalOcean's
create page: *"The most popular defaults are pre-selected, so you can scroll to
the bottom of the page and create a Droplet immediately."* Johnson & Goldstein
(2003, Science) — opt-in→opt-out roughly doubled consent, 42%→82%. Only
non-committal defaults: nothing that adds to the total.

**Top abandonment reasons** (Baymard, 70.22% avg across 50 studies):
extra costs 40% · card distrust 19% · forced account 18% · too long 17% ·
can't see total up-front 12%. So: show the true total INCLUDING the renewal
price before any payment field, and visually ENCAPSULATE the card fields — in
testing the container did the work, not which seal was used.

**Pre-ticked paid add-ons are illegal in the EU.** CRD 2011/83/EU Art. 22: consent
inferred from a default the consumer must reject entitles them to
reimbursement. A pre-ticked backup is a chargeback generator. EU B2C must also

// Client-side deploy-funnel beacons. Dependency-free (no server imports) so it is
// safe to pull into the customer wizard client components. Fires fire-and-forget
// POSTs to /api/track/deploy-step; never throws, never blocks the wizard.

export type DeployProduct = "vps" | "game" | "hosting" | "email";

/** Read the per-tab session id the VisitTracker maintains, so a funnel event can
 *  be tied to the same session as the pageviews. */
function sessionId(): string | null {
  try {
    return window.sessionStorage.getItem("nx_sid");
  } catch {
    return null;
  }
}

function send(payload: Record<string, unknown>): void {
  try {
    const body = JSON.stringify({ ...payload, sessionId: sessionId() });
    if (typeof navigator !== "undefined" && navigator.sendBeacon) {
      navigator.sendBeacon("/api/track/deploy-step", new Blob([body], { type: "application/json" }));
    } else {
      fetch("/api/track/deploy-step", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
        keepalive: true,
      }).catch(() => {});
    }
  } catch {
    /* best-effort */
  }
}

/**
 * Record that the user REACHED a wizard step. De-duped per tab-session so a
 * component re-render / strict-mode double-mount doesn't count a step twice — the
 * funnel measures distinct sessions reaching each step.
 */
export function trackDeployStep(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfstep:${product}:${stepIndex}:${step}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* storage disabled — still emit, just without cross-render dedupe */
  }
  send({ product, step, stepIndex, type: "step" });
}

/**
 * Record that a wizard step FAILED (a validation error, or an API/provision call
 * that returned/raised an error). NOT de-duped — every real failure is a signal.
 */
export function trackDeployError(
  product: DeployProduct,
  step: string,
  stepIndex: number,
  errorCode: string,
  errorMessage?: string,
): void {
  if (typeof window === "undefined") return;
  send({ product, step, stepIndex, type: "error", errorCode, errorMessage: errorMessage ?? null });
}

/** Record that the deploy SUCCEEDED (bottom of the funnel). De-duped per session. */
export function trackDeployComplete(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfdone:${product}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* ignore */
  }
  send({ product, step, stepIndex, type: "complete" });
}

/** What a wizard selection tracks: which game family, plan/tier, billing term
 *  or region a customer clicked. Read side: lib/deploy-funnel.ts's
 *  `deploySelections` + lib/plan-popularity.ts (lines this up against real
 *  completed orders — "what people click" vs "what people buy"). */
export type DeploySelectKind = "game" | "plan" | "term" | "region" | "sea_price_test";

/**
 * Record a real SELECTION inside the wizard — as distinct from `trackDeployStep`,
 * which only says a STEP was reached, not what was picked on it.
 *
 * `value` is the primary identifier for `kind` (a game family slug, a
 * plan/tier id, a term in months as a string, a region key) and is folded
 * into `detail` as `detail.value` so the read side has one place to look;
 * `detail` can carry extra context alongside it (ramMB, price, …).
 *
 * NOT de-duped like trackDeployStep/trackDeployComplete — re-picking a
 * different tier after backing up is itself a real signal ("everyone clicks
 * the 16GB tier but buys the 4GB one"), so every click counts, not just the
 * first one per session.
 */
export function trackDeploySelect(
  product: DeployProduct,
  kind: DeploySelectKind,
  value: string,
  detail?: Record<string, unknown>,
): void {
  if (typeof window === "undefined") return;
  let detailStr: string | null = null;
  try {
    // Capped well under the API route's own 2000-char ceiling — this is a
    // small "what was picked" blob, not a place to stash arbitrary data.
    detailStr = JSON.stringify({ value, ...(detail ?? {}) }).slice(0, 2000);
  } catch {
    detailStr = null;
  }
  send({ product, step: kind, stepIndex: 0, type: "select", detail: detailStr });
}
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";

/**
 * Server-side helpers for the deploy-wizard funnel (DeployFunnelEvent).
 *
 * Two concerns live here:
 *  1. WRITE — `recordDeployFunnelError` / `recordDeployFunnelComplete` let the
 *     authoritative server paths (the payAndDeploy action, the order/provision
 *     code) stamp an error/complete event even when the browser never sees the
 *     outcome. Both are strictly best-effort: they swallow every failure so they
 *     can never disturb the money path they're instrumenting.
 *  2. READ — `deployFunnels` aggregates the raw events into the admin funnel view:
 *     per product, per step, how many REACHED it, how many of those COMPLETED the
 *     deploy, how many DROPPED OFF, and how many ERRORED (with the top error
 *     messages) — so an admin can tell "stuck on a BUG" from "just abandoned".
 */

const DAY = 86_400_000;
const EVENT_CAP = 100_000;

export type DeployProduct = "vps" | "game" | "hosting" | "email";

/**
 * Typed accessor for the DeployFunnelEvent delegate.
 *
 * The generated Prisma client in this worktree does not yet carry this model
 * (its node_modules is symlinked to prod, which we must not regenerate here — the
 * owner regenerates the client when they apply prisma/manual-migration-deploy-funnel.sql
 * at deploy). This shim types every read/write against the model's real shape so
 * call sites stay type-safe and `tsc` is clean now, and binds to the genuine
 * delegate the moment the client is regenerated. It is the ONLY place that reaches
 * for the delegate, so there is a single seam to delete once the model is generated.
 */
export type DeployFunnelEventRow = {
  id: string;
  userId: string | null;
  visitorId: string | null;
  sessionId: string | null;
  product: string;
  step: string;
  stepIndex: number;
  type: string;
  errorCode: string | null;
  errorMessage: string | null;
  /** (type="select" only) JSON string of what was picked — see the
   *  DeployFunnelEvent model's doc comment. NOT part of the generated
   *  client's DMMF in this worktree (see `insertDeployFunnelEvent` below) —
   *  present only in this hand-written row shape. */
  detail: string | null;
  createdAt: Date;
};

type DeployFunnelDelegate = {
  create(args: { data: Partial<DeployFunnelEventRow> }): Promise<DeployFunnelEventRow>;
  findMany(args: {
    where?: Record<string, unknown>;
    select?: Record<string, boolean>;
    take?: number;
    orderBy?: Record<string, "asc" | "desc">;
  }): Promise<DeployFunnelEventRow[]>;
};

function dfe(): DeployFunnelDelegate {
  return (db as unknown as { deployFunnelEvent: DeployFunnelDelegate }).deployFunnelEvent;
}

/** Low-level insert used by the /api/track/deploy-step route (and internally).
 *  Fire-and-forget; never throws.
 *
 * `detail` (the "select" event payload) is NOT part of the generated Prisma
 * client's compiled schema in this worktree (see the seam comment above) —
 * confirmed directly: passing it to `dfe().create()` throws
 * `PrismaClientValidationError: Unknown argument 'detail'`, because the
 * shared/symlinked client's DMMF was compiled before this column existed.
 * Raw SQL bypasses that entirely, so a row carrying `detail` is inserted with
 * `$executeRaw` instead of the typed delegate; every other event keeps using
 * the normal typed path unchanged. */
export async function insertDeployFunnelEvent(data: Partial<DeployFunnelEventRow>): Promise<void> {
  try {
    if (data.detail != null) {
      await db.$executeRaw`
        INSERT INTO "DeployFunnelEvent"
          ("id","userId","visitorId","sessionId","product","step","stepIndex","type","errorCode","errorMessage","detail","createdAt")
        VALUES (
          ${data.id ?? randomUUID()}, ${data.userId ?? null}, ${data.visitorId ?? null}, ${data.sessionId ?? null},
          ${data.product ?? ""}, ${data.step ?? ""}, ${data.stepIndex ?? 0}, ${data.type ?? "step"},
          ${data.errorCode ?? null}, ${data.errorMessage ?? null}, ${data.detail},
          ${data.createdAt ?? new Date()}
        )
      `;
      return;
    }
    await dfe().create({ data });
  } catch {
    /* best-effort analytics — never disturb the caller */
  }
}

/** Record a deploy failure server-side. Fire-and-forget; never throws. */
export async function recordDeployFunnelError(input: {
  product: DeployProduct;
  step: string;
  stepIndex: number;
  errorCode: string;
  errorMessage?: string | null;
  userId?: string | null;
  /** Optional small JSON context (e.g. `{"serverId","game","nodeId"}` for a
   *  PROVISION_FAILED) so /admin/reports can group failures by game and node
   *  even after the server row is deleted. Capped at 500 chars. */
  detail?: Record<string, unknown> | null;
}): Promise<void> {
  let detail: string | null = null;
  try {
    detail = input.detail ? JSON.stringify(input.detail).slice(0, 500) : null;
  } catch {
    detail = null;
  }
  await insertDeployFunnelEvent({
    product: input.product,
    step: input.step.slice(0, 60),
    stepIndex: Math.max(0, Math.min(50, Math.round(input.stepIndex))),
    type: "error",
    errorCode: input.errorCode.slice(0, 60),
    errorMessage: input.errorMessage ? input.errorMessage.slice(0, 300) : null,
    userId: input.userId ?? null,
    detail,
  });
}

/** Record a successful deploy server-side. Fire-and-forget; never throws. */
export async function recordDeployFunnelComplete(input: {
  product: DeployProduct;
  step: string;
  stepIndex: number;
  userId?: string | null;
}): Promise<void> {
  await insertDeployFunnelEvent({
    product: input.product,
    step: input.step.slice(0, 60),
    stepIndex: Math.max(0, Math.min(50, Math.round(input.stepIndex))),
    type: "complete",
    userId: input.userId ?? null,
  });
}

// ---- Read side: aggregate events into the funnel view ----

export type ErrorTally = { code: string | null; message: string | null; count: number };

export type FunnelStep = {
  step: string;
  /** Ordering position (min observed stepIndex for this step within the product). */
  order: number;
  /** Distinct sessions that reached this step. */
  reached: number;
  /** Of those, how many ultimately completed the deploy. */
  completedThrough: number;
  /** Distinct sessions that dropped off AT this step (reached here, not the next). */
  abandoned: number;
  /** Drop-off share at this step (abandoned / reached), 0..1. */
  dropOffRate: number;
  /** Distinct sessions that hit an error on this step. */
  erroredSessions: number;
  /** Total error events on this step (a session can error more than once). */
  errorEvents: number;
  /** Most common error codes/messages on this step. */
  topErrors: ErrorTally[];
};

export type ProductFunnel = {
  product: DeployProduct;
  /** Distinct sessions that reached the first step (top of funnel). */
  started: number;
  /** Distinct sessions with a completed deploy. */
  completed: number;
  /** Distinct sessions that errored anywhere. */
  erroredSessions: number;
  steps: FunnelStep[];
};

/** Stable identity for one wizard run: session, else visitor, else account, else row. */
function identity(e: { sessionId: string | null; visitorId: string | null; userId: string | null; id: string }): string {
  return e.sessionId ?? e.visitorId ?? e.userId ?? e.id;
}

const PRODUCTS: DeployProduct[] = ["vps", "game", "hosting", "email"];

/**
 * Build the per-product deploy funnel over the trailing `days` window. Read-only,
 * window-scoped and take-capped so it stays cheap as the event log grows.
 */
export async function deployFunnels(days = 30): Promise<ProductFunnel[]> {
  const since = new Date(Date.now() - days * DAY);
  const events = await dfe().findMany({
    where: { createdAt: { gte: since } },
    select: {
      id: true,
      product: true,
      step: true,
      stepIndex: true,
      type: true,
      errorCode: true,
      errorMessage: true,
      sessionId: true,
      visitorId: true,
      userId: true,
    },
    take: EVENT_CAP,
    orderBy: { createdAt: "desc" },
  });

  const out: ProductFunnel[] = [];

  for (const product of PRODUCTS) {
    const rows = events.filter((e) => e.product === product);
    if (rows.length === 0) continue;

    // Which runs completed the deploy (for completed-through per step + the
    // top-of-card completed count).
    //
    // IDENTITY RECONCILIATION. Completion is now recorded AUTHORITATIVELY on the
    // server (the shared placeOrder / placeGameOrder / placeHostingOrder success
    // paths — see lib/deploy-funnel `recordDeployFunnelComplete`), where the only
    // stable handle is the signed-in `userId`: a webhook-driven card fulfilment has
    // no browser session. The wizard's own `step` beacons, by contrast, key on the
    // per-tab `sessionId`. So a completion and the steps that led to it resolve to
    // DIFFERENT `identity()` strings, and matching purely on identity would report
    // every completed session as "abandoned at the last step". We therefore match a
    // completion to its run by `userId` (every deploy requires login, so both sides
    // carry one), falling back to identity for any legacy client-side complete that
    // had no account attributed.
    const completedUserIds = new Set<string>();
    const completedIdentityIds = new Set<string>();
    for (const e of rows) {
      if (e.type !== "complete") continue;
      if (e.userId) completedUserIds.add(e.userId);
      else completedIdentityIds.add(identity(e));
    }
    // identity → the account that owns that run, so a `sessionId`-keyed step can be
    // tied back to a `userId`-keyed completion. First non-null userId per identity.
    const userOf = new Map<string, string>();

    // Per-step aggregation.
    type Acc = {
      order: number;
      reached: Set<string>;
      errored: Set<string>;
      errorEvents: number;
      errors: Map<string, { code: string | null; message: string | null; count: number }>;
    };
    const byStep = new Map<string, Acc>();
    const erroredAnywhere = new Set<string>();

    const ensure = (step: string, stepIndex: number): Acc => {
      let a = byStep.get(step);
      if (!a) {
        a = { order: stepIndex, reached: new Set(), errored: new Set(), errorEvents: 0, errors: new Map() };
        byStep.set(step, a);
      } else if (stepIndex < a.order) {
        a.order = stepIndex; // keep the earliest observed position for ordering
      }
      return a;
    };

    for (const e of rows) {
      const id = identity(e);
      if (e.userId && !userOf.has(id)) userOf.set(id, e.userId);
      if (e.type === "step") {
        ensure(e.step, e.stepIndex).reached.add(id);
      } else if (e.type === "error") {
        const a = ensure(e.step, e.stepIndex);
        a.errored.add(id);
        a.errorEvents += 1;
        erroredAnywhere.add(id);
        const key = `${e.errorCode ?? ""}�${e.errorMessage ?? ""}`;
        const cur = a.errors.get(key) ?? { code: e.errorCode, message: e.errorMessage, count: 0 };
        cur.count += 1;
        a.errors.set(key, cur);
      }
    }

    const ordered = [...byStep.entries()]
      .map(([step, a]) => ({ step, a }))
      .sort((x, y) => x.a.order - y.a.order || x.step.localeCompare(y.step));

    // Did the run behind this step identity complete? By userId (the authoritative
    // server-side key) first, then a direct identity hit for legacy client completes.
    const runCompleted = (id: string): boolean => {
      if (completedIdentityIds.has(id)) return true;
      const u = userOf.get(id);
      return u != null && completedUserIds.has(u);
    };

    // Distinct completed runs: accounts that completed, plus any accountless legacy
    // completion. The two sets are disjoint by construction.
    const completed = completedUserIds.size + completedIdentityIds.size;

    const steps: FunnelStep[] = ordered.map(({ step, a }, i) => {
      const reached = a.reached.size;
      const next = ordered[i + 1];
      // Sessions continuing past this step = reached the next step (or, on the last
      // step, completed the deploy). Everyone else abandoned here.
      const continued = next
        ? [...a.reached].filter((id) => next.a.reached.has(id)).length
        : [...a.reached].filter((id) => runCompleted(id)).length;
      const abandoned = Math.max(0, reached - continued);
      const completedThrough = [...a.reached].filter((id) => runCompleted(id)).length;
      const topErrors = [...a.errors.values()].sort((p, q) => q.count - p.count).slice(0, 3);
      return {
        step,
        order: a.order,
        reached,
        completedThrough,
        abandoned,
        dropOffRate: reached > 0 ? abandoned / reached : 0,
        erroredSessions: a.errored.size,
        errorEvents: a.errorEvents,
        topErrors,
      };
    });

    out.push({
      product,
      started: steps[0]?.reached ?? 0,
      completed,
      erroredSessions: erroredAnywhere.size,
      steps,
    });
  }

  return out;
}

