//
// Distinct from `deployFunnels` above (which measures how far a session gets)
// and from `lib/plan-popularity.ts` (which measures what people actually BUY,
// off the real Server/HostingAccount/EmailSubscription tables). This is the
// weaker, in-between signal: which game/plan/term/region a customer clicked in
// the wizard, whether or not they ever completed the order — useful mainly
// lined up NEXT TO the real-order numbers (see lib/plan-popularity.ts's
// `considerVsBought`), e.g. "everyone clicks the 16GB tier but buys the 4GB
// one."

export type SelectionTally = { value: string; count: number };
export type ProductSelectionKind = { kind: string; tallies: SelectionTally[] };
export type ProductSelections = { product: DeployProduct; kinds: ProductSelectionKind[] };

type RawSelectRow = { product: string; step: string; detail: string | null };

/**
 * Build the per-product, per-kind selection tallies over the trailing `days`
 * window. Read-only, raw SQL (see `insertDeployFunnelEvent`'s note — `detail`
 * isn't in this worktree's generated client's DMMF, so `$queryRaw` is used
 * instead of `dfe().findMany()`, which would throw on an unknown `select`
 * field the same way `create()` does on an unknown `data` field).
 */
export async function deploySelections(days = 30): Promise<ProductSelections[]> {
  const since = new Date(Date.now() - days * DAY);
  let rows: RawSelectRow[];
  try {
    rows = await db.$queryRaw<RawSelectRow[]>`
      SELECT "product", "step", "detail"
      FROM "DeployFunnelEvent"
      WHERE "type" = 'select' AND "createdAt" >= ${since}
      ORDER BY "createdAt" DESC
      LIMIT ${EVENT_CAP}
    `;
  } catch {
    // Table/column not reachable (e.g. the manual migration hasn't been
    // applied to this DB yet) — degrade to "no selection data" rather than
    // let a read-only analytics view throw.
    return [];
  }

  const out: ProductSelections[] = [];
  for (const product of PRODUCTS) {
    const productRows = rows.filter((r) => r.product === product);
    if (productRows.length === 0) continue;

    // kind (the select's `step`) -> value (parsed out of `detail`) -> count
    const byKind = new Map<string, Map<string, number>>();
    for (const r of productRows) {
      let value: string | null = null;
      if (r.detail) {
        try {
          const parsed = JSON.parse(r.detail) as { value?: unknown };
          if (typeof parsed.value === "string" && parsed.value) value = parsed.value;
        } catch {
          /* malformed detail — skip this row rather than count a bad value */
        }
      }
      if (!value) continue;
      const tallies = byKind.get(r.step) ?? new Map<string, number>();
      tallies.set(value, (tallies.get(value) ?? 0) + 1);
      byKind.set(r.step, tallies);
    }

    out.push({
      product,
      kinds: [...byKind.entries()].map(([kind, tallies]) => ({
        kind,
        tallies: [...tallies.entries()]
          .map(([value, count]) => ({ value, count }))
          .sort((a, b) => b.count - a.count),
      })),
    });
  }
  return out;
}

/** Sum selection tallies for one `kind` across several products into a single
 *  ranked list — e.g. "term" selections are made on every product's own
 *  TermChips, but the real-order term distribution (`lib/plan-popularity.ts`)
 *  is counted across all of them together, so the two need to be compared on
 *  the same combined basis. */
export function mergeSelectionTallies(
  selections: ProductSelections[],
  products: DeployProduct[],
  kind: string,
): SelectionTally[] {
  const totals = new Map<string, number>();
  for (const p of selections) {
    if (!products.includes(p.product)) continue;
    const k = p.kinds.find((x) => x.kind === kind);
    if (!k) continue;
    for (const t of k.tallies) totals.set(t.value, (totals.get(t.value) ?? 0) + t.count);
  }
  return [...totals.entries()]
    .map(([value, count]) => ({ value, count }))
    .sort((a, b) => b.count - a.count);
}

