/** Build the picker's region list from the nodes that actually exist.
 *
 * Sorted by region KEY, not by whatever order the `nodes` array arrived in.
 * The caller's `Node` query has no natural order of its own (Postgres makes
 * no ordering guarantee without an explicit `orderBy`), so building this Map
 * straight off it made the region list — and, worse, "region #0", the wizard's
 * SEEDED DEFAULT — reshuffle from one page load to the next. A customer could
 * land on a random datacentre with no region actually chosen. Sorting here
 * makes the list (and anything that reads `regions[0]`) deterministic
 * regardless of query order; `defaultRegionKey` below is the real "which one
 * should be picked FOR the customer" decision. */
export function regionsFrom(nodes: { id: string; region: string }[]): Region[] {
  const byRegion = new Map<string, string[]>();
  for (const n of nodes) {
    if (!COORDS[n.region]) continue; // no coordinates -> cannot be drawn, so not offered
    const list = byRegion.get(n.region) ?? [];
    list.push(n.id);
    byRegion.set(n.region, list);
  }
  return [...byRegion.entries()]
    .map(([code, nodeIds]) => {
      const c = COORDS[code];
      return {
        key: code,
        name: REGION_LABELS[code] ?? code,
        area: c.area,
        flag: REGION_COUNTRY[code] ?? "sg",
        lat: c.lat,
        lon: c.lon,
        ms: c.ms,
        nodeIds,
      };
    })
    .sort((a, b) => a.key.localeCompare(b.key));
}

