 * label. Otherwise a FIXED, deterministic default: Singapore (`sgp1`), the
 * platform's original/primary node, chosen because it's the platform's real
 * primary location — never "whichever region a `Node` query happened to
 * return first," which is how a customer could previously land on a random
 * datacentre with no region actually chosen (app/dashboard/deploy/page.tsx).
 * Falls back to the first region in the alphabetically-stable list above if
 * even Singapore isn't offered (e.g. on a differently-configured environment).
 */
export function defaultRegionKey(regions: Region[], visitorCountry: string | null): string | null {
  return defaultRegionChoice(regions, visitorCountry).region;
}

/**
 * Which region the wizard preselects and why (2026-10-01). Geography by
 * country (SEA/AU/IN/JP/KR -> sgp1, EU/MENA/Africa -> fsn1, Americas -> bhs1,
 * unknown -> sgp1) via lib/region-pick.ts; if that region is sold out the
 * nearest region with room is preselected instead and `note` says so. The
 * order is always submitted with this explicit region.
 */
export function defaultRegionChoice(
  regions: Region[],
  visitorCountry: string | null,
): { region: string | null; source: "geo" | "default"; note: string | null } {
  const availability: RegionStatusMap = {};
  for (const r of regions) availability[r.key] = r.availability ?? "available";
  const pick = preselectRegion({ country: visitorCountry, availability, regionKeys: regions.map((r) => r.key) });
  const source = regionForCountry(visitorCountry).known ? "geo" : "default";
  let note: string | null = null;
  if (pick.movedBecauseFull && pick.region) {
    const from = REGION_LABELS[pick.geoRegion] ?? pick.geoRegion;
    const to = REGION_LABELS[pick.region] ?? pick.region;
    note = `We preselected ${to}, where your server can be live fastest right now. Prefer ${from}? Pick it below and we'll have it ready for you there.`;
