   Control panels and applications have their own drawn marks in the app sprite
   sheet; the interface icon set has no cPanel or WordPress glyph, so falling
   back to it renders every one of them as the same generic cube.

   Template names carry qualifiers the sheet's keys do not — "Caddy (auto-SSL)",
   "WireGuard VPN", "Uptime Kuma (monitoring)" — so match progressively rather
   than demanding an exact string. */
export function appSpriteKey(name: string): string | null {
  if (APP[name]) return name;
  // drop a parenthetical: "Pi-hole (ad blocker)" -> "Pi-hole"
  const bare = name.replace(/\s*\(.*\)\s*$/, "").trim();
  if (APP[bare]) return bare;
  // longest key that the name starts with: "WireGuard VPN" -> "WireGuard"
  let best: string | null = null;
  for (const k of Object.keys(APP)) {
    if (bare.toLowerCase().startsWith(k.toLowerCase()) && (!best || k.length > best.length)) best = k;
  }
  return best;
}

