 * Callers: the PayPal capture server action (client-driven, like Stripe's confirm
 * redirect) AND the PayPal webhook (the reliable backstop) — the SAME
 * confirm/webhook race Stripe already runs safely, because the claim below is the
 * same `FulfilledSession` UNIQUE(stripeSessionId) index, just keyed
 * `"paypal:<orderId>"` instead of a Stripe session id. Coinbase Commerce has no
 * client-driven capture step (crypto confirmation only ever arrives by webhook),
 * so its webhook is the only caller — still idempotent on its own if Coinbase ever
 * redelivers the event.
 *
 * THROWS if the `PendingExternalPayment` row cannot be found or its stored
 * metadata is not valid JSON — the same "throw rather than silently misclassify"
 * discipline `retrieveCheckoutSession` and `fulfilCheckoutSession` already apply
 * to a Stripe read failure. A row that cannot be trusted must never fall through
 * to the top-up branch.
 */
export async function fulfilExternalPayment(input: ExternalPaymentInput): Promise<FulfilResult> {
  const row = await db.pendingExternalPayment.findUnique({ where: { id: input.pendingId } });
  if (!row) {
    throw new Error(`No PendingExternalPayment row for id ${input.pendingId} (${input.provider} ${input.externalId})`);
  }
  if (row.provider !== input.provider) {
    throw new Error(
      `PendingExternalPayment ${input.pendingId} provider mismatch: expected ${input.provider}, stored ${row.provider}`,
    );
  }

  let metadata: Record<string, string>;
  try {
    const parsed = JSON.parse(row.metadata);
    if (!parsed || typeof parsed !== "object") throw new Error("not an object");
    metadata = parsed as Record<string, string>;
  } catch {
    throw new Error(`PendingExternalPayment ${input.pendingId} metadata is not readable JSON`);
  }

  // The provider-qualified id IS the FulfilledSession/WalletTransaction claim key —
  // "paypal:5O190127TN364715T" can never collide with a real Stripe `cs_...` id or
  // with the other provider's charge codes.
  const sessionId = `${input.provider}:${input.externalId}`;
  const synthetic = {
    id: sessionId,
    metadata,
    payment_status: "paid",
    amount_total: row.amountCents,
    currency: row.currency,
    customer: null,
    payment_intent: null,
  } as unknown as Stripe.Checkout.Session;

  const purpose = classifyCheckoutSession(synthetic);

  // Payment record (lib/payment-events.ts): the provider confirmed the money. Keyed
  // on the provider id so the capture call and the provider webhook write it once.
  await recordPayment({
    type: "payment.succeeded", outcome: "succeeded", provider: input.provider, userId: row.userId,
    method: input.provider, amountCents: row.amountCents, currency: row.currency, reference: input.externalId,
    dedupeKey: `${sessionId}:succeeded`,
    label: `Paid ${(row.amountCents / 100).toFixed(2)} ${row.currency.toUpperCase()} by ${input.provider === "paypal" ? "PayPal" : "crypto (Coinbase)"} for ${purposeLabel(purposeFromMetadata(metadata))}`,
    data: { purpose: purposeFromMetadata(metadata), kind: row.kind },
  });

  try {
    const result = await runFulfilment(synthetic, purpose, input.base ?? "", input.provider);
    await db.pendingExternalPayment
      .update({ where: { id: row.id }, data: { status: "PAID", providerRef: input.externalId } })
      .catch(() => {});
    return result;
  } catch (e) {
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
    throw e;
  }
}

// Re-exported so callers building a PendingExternalPayment row's `metadata`
// column can reuse the SAME 500-char-per-value refuse-don't-truncate guard
// Stripe metadata uses, instead of a second copy of that safety property.
const PAYPAL_HOLD_MS = 3 * 60 * 60 * 1000 + RESERVATION_GRACE_MS;
const COINBASE_HOLD_MS = 60 * 60 * 1000 + RESERVATION_GRACE_MS;

function appBase(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

// NOTE: whether PayPal/Coinbase are configured is intentionally NOT exposed from
// this file. Every export of a "use server" module is a public, network-callable
// endpoint (see test/auth-lockouts.test.ts's HAZARD suite) — a plain env-var
// read has nothing to authenticate, so it belongs in a plain module instead of
// minting an unauthenticated endpoint for no reason. Server components read
// `paypalConfigured()` / `coinbaseConfigured()` / `paypalClientIdPublic()`
// directly from lib/paypal.ts and `coinbaseConfigured()` from
// lib/coinbase-commerce.ts (neither file has "use server") and pass the booleans
// down as plain props, the same way `stripeConfigured()` already does.

export type CreatePayPalOrderResult = { error: string } | { paypalOrderId: string; pendingId: string };
export type CreateCoinbaseChargeResult = { error: string } | { hostedUrl: string; pendingId: string };

async function openPayPal(opts: {
  userId: string;
  kind: string;
  amountCents: number;
  metadata: Record<string, string>;
  description: string;
}): Promise<{ error: string } | { paypalOrderId: string; pendingId: string }> {
  if (!paypalConfigured()) return { error: "PayPal isn't set up yet — try another payment method." };
  // Admin kill switch (/admin/settings → Payments) — checked here too, not just
  // in the prop that hides the row client-side, so disabling PayPal actually
  // blocks it even if this action is called directly.
  if (!(await getSettingBool("payments_paypal_enabled", true))) {
    return { error: "PayPal is temporarily unavailable — try another payment method." };
  }
  const row = await db.pendingExternalPayment.create({
    data: {
      provider: "paypal",
      kind: opts.kind,
      userId: opts.userId,
      amountCents: opts.amountCents,
      currency: "usd",
      metadata: JSON.stringify(opts.metadata),
    },
  });
  try {
    // vault: true on every PayPal payment (top-up or purchase alike) — the
    // same "always try to save a chargeable method" posture Stripe already
    // gets from setting `setup_future_usage: 'off_session'` on every card
    // session. Best-effort: PayPal may decline to vault without failing the
    // payment itself (see createPayPalOrder's doc comment).
    const order = await createPayPalOrder({ amountCents: opts.amountCents, pendingId: row.id, description: opts.description, vault: true });
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { providerRef: order.id } }).catch(() => {});
    await recordPayment({
      type: "payment.checkout_opened", outcome: "opened", provider: "paypal", userId: opts.userId, method: "paypal",
      amountCents: opts.amountCents, reference: order.id, dedupeKey: `checkout-opened:paypal:${order.id}`,
      label: `Opened PayPal checkout (${(opts.amountCents / 100).toFixed(2)} USD, ${opts.kind})`, data: { kind: opts.kind },
    });
    return { paypalOrderId: order.id, pendingId: row.id };
  } catch (e) {
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
    console.error("[payments] could not create PayPal order", e);
    return { error: "We couldn't start the PayPal payment — please try again." };
  }
}

async function openCoinbase(opts: {
  userId: string;
  kind: string;
  amountCents: number;
  metadata: Record<string, string>;
  name: string;
  description: string;
  redirectPath: string;
  cancelPath: string;
}): Promise<{ error: string } | { hostedUrl: string; pendingId: string }> {
  if (!coinbaseConfigured()) return { error: "Crypto payments aren't set up yet — try another payment method." };
  // Admin kill switch (/admin/settings → Payments) — same defense-in-depth as
  // openPayPal above.
  if (!(await getSettingBool("payments_coinbase_enabled", true))) {
    return { error: "Crypto payments are temporarily unavailable — try another payment method." };
  }
  const row = await db.pendingExternalPayment.create({
    data: {
      provider: "coinbase",
      kind: opts.kind,
      userId: opts.userId,
      amountCents: opts.amountCents,
      currency: "usd",
      metadata: JSON.stringify(opts.metadata),
    },
  });
  try {
    const charge = await createCoinbaseCharge({
      amountCents: opts.amountCents,
      pendingId: row.id,
      name: opts.name,
      description: opts.description,
      redirectUrl: `${appBase()}${opts.redirectPath}`,
      cancelUrl: `${appBase()}${opts.cancelPath}`,
    });
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { providerRef: charge.code } }).catch(() => {});
    await recordPayment({
      type: "payment.checkout_opened", outcome: "opened", provider: "coinbase", userId: opts.userId, method: "crypto",
      amountCents: opts.amountCents, reference: charge.code, dedupeKey: `checkout-opened:coinbase:${charge.code}`,
      label: `Opened crypto checkout (${(opts.amountCents / 100).toFixed(2)} USD, ${opts.kind})`, data: { kind: opts.kind },
    });
    return { hostedUrl: charge.hosted_url, pendingId: row.id };
  } catch (e) {
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
    console.error("[payments] could not create Coinbase Commerce charge", e);
    return { error: "We couldn't start the crypto payment — please try again." };
  }
}

/**
 * Capture a PayPal order server-to-server and fulfil it — the PayPal analogue of
 * the Stripe confirm route (app/api/stripe/confirm/route.ts). Called from the
 * wizard's `onApprove` callback; the PayPal webhook is the reliable backstop for
 * the same reason the Stripe webhook is (a closed tab must not be the only thing
 * that could have fulfilled a paid order). Idempotent via `fulfilExternalPayment`'s
 * FulfilledSession claim, so this racing the webhook is safe.
 */
export async function captureExternalPayPalOrder(
  paypalOrderId: string,
  pendingId: string,
): Promise<{ redirect?: string; error?: string }> {
  const user = await requireUser();
  const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
  if (!row || row.userId !== user.id || row.provider !== "paypal") {
    return { error: "We couldn't find that payment." };
  }

  let captured;
  try {
    captured = await capturePayPalOrder(paypalOrderId);
  } catch (e) {
    console.error("[payments] PayPal capture failed", paypalOrderId, e);
    await recordPayment({
      type: "payment.failed", outcome: "failed", provider: "paypal", userId: user.id, method: "paypal",
      amountCents: row.amountCents, reference: paypalOrderId, dedupeKey: `paypal:${paypalOrderId}:capture_error`,
      label: `PayPal capture failed (${(row.amountCents / 100).toFixed(2)} USD)`, data: { kind: row.kind, reason: "capture error" },
    });
    return { error: "We couldn't confirm that PayPal payment. If you were charged, contact support — your money is safe." };
  }
  if (captured.status !== "COMPLETED") {
    await recordPayment({
      type: "payment.failed", outcome: "failed", provider: "paypal", userId: user.id, method: "paypal",
      amountCents: row.amountCents, reference: paypalOrderId, dedupeKey: `paypal:${paypalOrderId}:${captured.status}`,
      label: `PayPal payment not completed: ${captured.status}`, data: { kind: row.kind, paypalStatus: captured.status },
    });
    return { error: `PayPal reported this payment as "${captured.status}" — please try again or use another method.` };
  }
  // Defence in depth: the captured amount must match what we asked PayPal to
  // charge. It always will (we set it), but a mismatch here means something is
  // wrong enough that fulfilling on trust would be the bug, not the fix.
  const capturedCents = Math.round(
    Number(captured.purchase_units?.[0]?.payments?.captures?.[0]?.amount?.value ?? "0") * 100,
  );
  if (capturedCents !== row.amountCents) {
    console.error("[payments] PayPal captured amount mismatch", { paypalOrderId, capturedCents, expected: row.amountCents });
    return { error: "That payment didn't match the expected amount. Contact support — nothing has been provisioned." };
  }

  // Best-effort, mirrors saveCardFromPaymentSession (lib/stripe-cards.ts): the
  // money has already been confirmed above, so a failure here must be inert
  // and never turn a successful payment into a reported error.
  const vault = vaultInfoFromCapture(captured);
  if (vault) {
    try {
      await db.user.update({
        where: { id: user.id },
        data: { paypalVaultId: vault.vaultId, paypalPayerEmail: vault.payerEmail },
      });
    } catch (e) {
      console.error("[payments] could not record vaulted PayPal method", e);
    }
  }

  try {
    const result: FulfilResult = await fulfilExternalPayment({
      provider: "paypal",
      externalId: paypalOrderId,
      pendingId,
      base: appBase(),
    });
    return { redirect: result.redirect };
  } catch (e) {
    console.error("[payments] PayPal fulfilment failed", paypalOrderId, e);
    return { error: "Your PayPal payment went through but we couldn't finish setup. Contact support — your money is safe and we've been alerted." };
  }
}

/* ------------------------------------------------------------------ *
 * VPS order — mirrors payAndDeploy's quote/promo/coupon/tax path
 * (lib/actions.ts) up to the point of opening a payment session.
 * ------------------------------------------------------------------ */

async function quoteVpsOrderForExternalPayment(formData: FormData): Promise<
  | { error: string }
  | {
      cardCents: number;
      metadata: Record<string, string>;
      release: () => Promise<void>;
    }
> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const limitErr = await serverLimitError(user.id);
  if (limitErr) return { error: limitErr };
  if (!res.ok) {
    const detail = json && typeof json === "object" ? JSON.stringify(json) : text;
    throw new Error(`PayPal API ${path} failed: ${res.status} ${detail}`.slice(0, 1000));
  }
  return json as T;
}

export type PayPalOrder = {
  id: string;
  status: string;
  purchase_units?: Array<{ custom_id?: string; amount?: { currency_code: string; value: string } }>;
};

/**
 * The vault block PayPal echoes back on a captured order's
 * `payment_source.paypal.attributes.vault` when vaulting was requested and
 * succeeded, plus the payer's PayPal email from `payment_source.paypal`
 * itself. Both are OPTIONAL in every response type below — vaulting is a
 * best-effort request, never assumed to have succeeded until this is present.
 */
export type PayPalVaultedOrder = PayPalOrder & {
  purchase_units?: Array<{
