/** Which product a Nxeon checkout paid for, from our own metadata keys. */
export function purposeFromMetadata(md: Record<string, string> | null | undefined): string {
  const m = md ?? {};
  if (m.nxeonOrder) return "vps_order";
  if (m.nxeonGameOrder) return "game_order";
  if (m.nxeonHostOrder) return "hosting_order";
  if (m.nxeonHostOrderSetup) return "hosting_card_setup";
  if (m.nxeonEmailOrder) return "email_order";
  if (m.nxeonDomainOrder) return "domain_order";
  if (m.nxeonResize) return "resize";
  if (m.nxeonDiskExpand) return "disk_expand";
  if (m.nxeonDedicatedIp) return "dedicated_ip";
  if (m.nxeonCardSetup) return "card_setup";
  if (m.nxeonChargeKey?.startsWith("renew:")) return "renewal";
  if (m.nxeonChargeKey) return "auto_recharge";
  return "topup";
}

const PURPOSE_LABEL: Record<string, string> = {
  vps_order: "VPS order",
  game_order: "game server order",
  hosting_order: "web hosting order",
  email_order: "business email order",
  domain_order: "domain order",
  resize: "server resize",
  disk_expand: "disk upgrade",
  dedicated_ip: "dedicated IPv4",
  card_setup: "saving a card",
  hosting_card_setup: "web hosting renewal card",
  renewal: "renewal",
  auto_recharge: "wallet auto-recharge",
  topup: "wallet top-up",
};

export function purposeLabel(p: string): string {
  return PURPOSE_LABEL[p] ?? p.replace(/_/g, " ");
}

function money(cents: number | null | undefined, currency: string | null | undefined): string {
  if (typeof cents !== "number") return "";
  const cur = (currency ?? "usd").toUpperCase();
  return `${(cents / 100).toFixed(2)} ${cur}`;
}

/** Method of a Checkout Session without another API call. */
export function sessionMethod(s: Pick<Stripe.Checkout.Session, "payment_method_types" | "metadata">): string {
  const local = s.metadata?.nxeonLocalPay;
  if (local) return local;
  const types = s.payment_method_types ?? [];
  if (types.length === 1) return types[0];
  if (types.length === 0) return "card";
  return types.includes("card") ? "card" : types.join("+");
}

/** Human reason for a failed PaymentIntent / card error (no free-text from the customer). */
export function failureReason(code: string | null | undefined, declineCode: string | null | undefined): string {
  const c = declineCode || code || "";
  const map: Record<string, string> = {
    insufficient_funds: "insufficient funds",
    card_declined: "card declined",
    generic_decline: "declined by the bank",
    do_not_honor: "declined by the bank (do not honor)",
    expired_card: "card expired",
    incorrect_cvc: "wrong CVC",
    incorrect_number: "wrong card number",
    processing_error: "processing error",
    lost_card: "card reported lost",
    stolen_card: "card reported stolen",
    fraudulent: "blocked as suspected fraud",
    authentication_required: "3-D Secure required",
    payment_intent_authentication_failure: "3-D Secure failed or abandoned",
    card_not_supported: "card type not supported",
    currency_not_supported: "currency not supported by the card",
    transaction_not_allowed: "transaction not allowed by the bank",
    withdrawal_count_limit_exceeded: "card limit exceeded",
    card_velocity_exceeded: "card limit exceeded",
  };
  return map[c] ?? (c ? c.replace(/_/g, " ") : "unknown reason");
}

/** Is this failure the 3-D Secure / authentication class (vs a plain decline)? */
export function isAuthFailure(code: string | null | undefined, declineCode?: string | null): boolean {
  return code === "authentication_required" || code === "payment_intent_authentication_failure" || declineCode === "authentication_required";
}

type Mapped = Omit<ActivityInput, "userId"> & { userId?: string | null; stripeCustomer?: string | null; paymentIntentId?: string | null };

function base(type: ActivityType, outcome: PaymentOutcome, extra: Partial<Mapped>): Mapped {
  return { type, outcome, provider: "stripe", ...extra };
}

/**
 * Pure: map a Stripe webhook event to the activity row it should produce
 * (userId resolved separately), or null when the event is not a payment
 * record we keep. Exported for tests.
 */
export function stripeEventToActivity(event: Stripe.Event): Mapped | null {
  const dedupeKey = `stripe:${event.id}`;
  const at = new Date(event.created * 1000);
  switch (event.type) {
    case "checkout.session.completed":
    case "checkout.session.async_payment_succeeded":
    case "checkout.session.async_payment_failed":
    case "checkout.session.expired": {
      const s = event.data.object as Stripe.Checkout.Session;
      if (s.mode === "setup") return null; // saving a card is not a payment
      const purpose = purposeFromMetadata(s.metadata as Record<string, string>);
      const method = sessionMethod(s);
      const amount = s.amount_total ?? null;
      const currency = s.currency ?? null;
      const country = s.customer_details?.address?.country ?? null;
      const common = {
        dedupeKey, createdAt: at, method, amountCents: amount, currency, country, reference: s.id,
        userId: s.metadata?.nxeonUserId ?? null,
        stripeCustomer: typeof s.customer === "string" ? s.customer : s.customer?.id ?? null,
        paymentIntentId: typeof s.payment_intent === "string" ? s.payment_intent : s.payment_intent?.id ?? null,
        data: { purpose, mode: s.mode, uiMode: s.ui_mode ?? null, paymentStatus: s.payment_status, creditUsdCents: s.metadata?.nxeonCreditUsdCents ? Number(s.metadata.nxeonCreditUsdCents) : null },
      } satisfies Partial<Mapped>;
