import { test, before } from "node:test";
import assert from "node:assert/strict";
import Stripe from "stripe";

/**
 * Payment records (lib/payment-events.ts) and the Stripe webhook route that
 * writes them (app/api/stripe/webhook/route.ts): event mapping, decline / 3-D
 * Secure classification, signature verification and idempotency on redelivery.
 *
 * A fake Prisma client is installed on globalThis before anything imports
 * lib/db (lib/db.ts reuses globalThis.prisma), and the events used against the
 * real route are ones that need no Stripe API call, so nothing here touches a
 * database or the network.
 */
type Row = Record<string, unknown>;
const activity: Row[] = [];
const notifications: Row[] = [];
(globalThis as unknown as { prisma: unknown }).prisma = {
  activityEvent: {
    async create({ data }: { data: Row }) {
      if (data.dedupeKey && activity.some((r) => r.dedupeKey === data.dedupeKey)) {
        throw Object.assign(new Error("Unique constraint failed on dedupeKey"), { code: "P2002" });
      }
      activity.push(data);
      return data;
    },
  },
  user: {
    async findFirst() { return null; },
    async findMany() { return [{ id: "admin1" }]; },
